const pptxgen = require("pptxgenjs");

// Color palette - security/technical theme
const COLORS = {
  darkBg: "0F172A",      // Deep slate for title slides
  primary: "1E3A5F",      // Deep blue
  accent: "0D9488",       // Teal - trust/security
  accentLight: "14B8A6",  // Light teal
  lightBg: "F8FAFC",      // Near white
  cardBg: "FFFFFF",       // White cards
  textDark: "1E293B",     // Slate dark
  textMuted: "64748B",    // Slate muted
  textLight: "F1F5F9",    // Light text
  danger: "DC2626",       // Red for failure modes
  warning: "F59E0B",      // Amber
  success: "059669",       // Green
  border: "E2E8F0",       // Light border
};

// Font pairings
