const pptxgen = require("pptxgenjs");

// Color palette - security/technical theme
const COLORS = {
  darkBg: "0F172A",      // Deep slate for title slides
  primary: "1E3A5F",      // Deep blue
  accent: "0D9488",       // Teal - trust/security
  accentLight: "14B8A6",  // Light teal
  lightBg: "F8FAFC",      // Near white
  cardBg: "FFFFFF",       // White cards
  textDark: "1E293B",     // Slate dark
  textMuted: "64748B",    // Slate muted
  textLight: "F1F5F9",    // Light text
  danger: "DC2626",       // Red for failure modes
  warning: "F59E0B",      // Amber
  success: "059669",       // Green
  border: "E2E8F0",       // Light border
};

// Font pairings
const FONTS = {
  header: "Arial Black",
  body: "Arial",
};

// Create presentation
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Research Team";
pres.title = "Auditing Model Substitution in LLM APIs";

// Helper: Create shadow (fresh object each time)
const makeShadow = () => ({
  type: "outer",
  color: "000000",
  blur: 8,
  offset: 3,
  angle: 135,
  opacity: 0.12,
});

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Accent bar at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.08,
  fill: { color: COLORS.accent },
});

// Main title
slide1.addText("Auditing Model Substitution in LLM APIs", {
  x: 0.6, y: 1.4, w: 8.8, h: 1.2,
  fontSize: 36, fontFace: FONTS.header, color: COLORS.textLight,
  bold: true, align: "left", valign: "middle",
});

// Subtitle
slide1.addText("Why Software Tests Fail and Hardware Attestation Wins", {
  x: 0.6, y: 2.6, w: 8.8, h: 0.6,
  fontSize: 22, fontFace: FONTS.body, color: COLORS.accentLight,
  align: "left",
});

// Tagline
slide1.addText("Commercial LLM API providers may covertly substitute cheaper models.\nThis work shows software-based detection is unreliable and proposes TEEs as a provably secure alternative.", {
  x: 0.6, y: 3.5, w: 7.5, h: 0.9,
  fontSize: 14, fontFace: FONTS.body, color: COLORS.textMuted,
  align: "left",
});

// Source reference
slide1.addText("Based on arxiv.org/abs/2504.04715", {
  x: 0.6, y: 5.1, w: 4, h: 0.3,
  fontSize: 11, fontFace: FONTS.body, color: COLORS.textMuted, italic: true,
});

// Audience tag
slide1.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 7.5, y: 4.8, w: 2.2, h: 0.5,
