});
slide1.addText("ML Researchers • AI Security Practitioners • Cloud Engineers", {
  x: 7.5, y: 4.8, w: 2.2, h: 0.5,
  fontSize: 8, fontFace: FONTS.body, color: COLORS.textLight,
  align: "center", valign: "middle",
});

